  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills pipes within the specified distance from the source using BFS-style expansion along connected pipes.
   * Algorithm:
   *   1. If this is the first call (distance == 1), call fillBeginTile() to mark source as filled
   *   2. Perform BFS from the source cell, expanding outward up to the given distance
   *   3. For each pipe cell encountered, check if adjacent pipes have matching connection directions (one pipe's direction must be opposite of the other)
   *   4. Mark reachable pipes as filled (set pipe.filled = true)
   *   5. Add newly filled tile coordinates to filledTiles list
   *   6. Update prevFilledTiles with the count of newly filled tiles in this round
   * Related Features: filledTiles field, prevFilledTiles field, sourceCell field, fillBeginTile(), Cell family fields
   * Related Classes: Coordinate, FillableCell, TerminationCell, Pipe, Direction, PipeShape
   * Input: distance : int - the maximum BFS depth to fill (positive integer)
   * Output: void
   * Pre-condition: distance >= 1
   * Post-condition: All pipes within the specified distance that are connected via matching directions are marked as filled, and filledTiles list is updated.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance == 1) {
        fillBeginTile();
    }
    
    // BFS from source cell
    TerminationCell source = getSourceCell();
    Coordinate sourceCoord = source.getCoord();
    
    // Use a queue for BFS
    java.util.Queue<Coordinate> queue = new java.util.LinkedList<>();
    boolean[][] visited = new boolean[getRows()][getCols()];
    
    queue.add(sourceCoord);
    visited[sourceCoord.getRow()][sourceCoord.getCol()] = true;
    
    int newlyFilled = 0;
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    
    while (!queue.isEmpty()) {
        Coordinate current = queue.poll();
        int curRow = current.getRow();
        int curCol = current.getCol();
        
        // Check all 4 directions
        for (Direction dir : Direction.VALUES) {
            Coordinate offset = helper.getOffset(dir);
            int nextRow = curRow + offset.getRow();
            int nextCol = curCol + offset.getCol();
            
            // Check bounds
            if (nextRow < 0 || nextRow >= getRows() || nextCol < 0 || nextCol >= getCols()) {
                continue;
            }
            
            if (visited[nextRow][nextCol]) {
                continue;
            }
            
            Cell nextCell = getCell()[nextRow][nextCol];
            if (!(nextCell instanceof FillableCell)) {
                continue;
            }
            
            FillableCell fillableCell = (FillableCell) nextCell;
            Pipe pipe = fillableCell.getPipe();
            if (pipe == null) {
                continue;
            }
            
            // Check if the pipe's connections include the opposite direction
            Direction oppositeDir = helper.getOpposite(dir);
            if (!pipe.getConnections().contains(oppositeDir)) {
                continue;
            }
            
            // Also check if the current cell has a matching connection
            // For source cell, use pointingTo
            // For other cells, check their pipe's connections
            boolean currentMatches = false;
            if (current.equals(sourceCoord)) {
                // Source cell
                if (source.getPointingTo() == dir) {
                    currentMatches = true;
                }
            } else {
                Cell curCell = getCell()[curRow][curCol];
                if (curCell instanceof FillableCell) {
                    FillableCell curFillable = (FillableCell) curCell;
                    Pipe curPipe = curFillable.getPipe();
                    if (curPipe != null && curPipe.getConnections().contains(dir)) {
                        currentMatches = true;
                    }
                }
            }
            
            if (!currentMatches) {
                continue;
            }
            
            // Mark as filled
            pipe.setFilled(true);
            
            // Add to filledTiles
            Coordinate tileCoord = Pa19Factory.eINSTANCE.createCoordinate();
            tileCoord.setRow(nextRow);
            tileCoord.setCol(nextCol);
            getFilledTiles().add(tileCoord);
            
            newlyFilled++;
            
            visited[nextRow][nextCol] = true;
            
            // Calculate BFS distance
            // We need to track distance from source
            // Let me use a different approach...
        }
    }
    
    prevFilledTiles = newlyFilled;
}

